%dw 2.0
output application/json
---
{
	query: {
		find: p('mongo-db-sapi.collections.resource-sharing-panel') default "DASHBOARD_COMPARTE_RECURSOS",
		filter: {
			Numero_Conexion: vars.connectionNumber
		},
		limit: 10
	}
}

%dw 2.0
output application/json
---
{
	query: {
		find: p('mongo-db-sapi.collections.resource-sharing-panel') default "DASHBOARD_COMPARTE_RECURSOS",
		filter: {
			Numero_Conexion: vars.connectionNumber
		},
		limit: 1
	}
}

%dw 2.0
output application/json
var lineaPadre = vars.connectionNumber
---
{
	query: {
		aggregate: "MDM_SERVICIO_ACTIVO",
		pipeline: [
			{
				"\$match": {
					Numero_Conexion: lineaPadre,
					Estado: { "\$in": ["Activo", "Suspendido"] }
				}
			},
			{
				"\$sort": {
					Fecha_Actualizacion: -1
				}
			},
			{
				"\$limit": 1
			},
			{
				"\$project": {
					"_id": 0,
					Numero_Conexion: 1,
					Estado: 1,
					Cuenta_Facturacion: 1
				}
			},
			{
				"\$lookup": {
					from: "MDM_CUENTA_FACTURACION",
					localField: "Cuenta_Facturacion",
					foreignField: "Cuenta_Facturacion",
					pipeline: [
						{
							"\$match": {
								Estado: { "\$in": ["A", "ACTIVO"] }
							}
						},
						{
							"\$sort": {
								Fecha_Modificacion: -1
							}
						},
						{
							"\$project": {
								"_id": 0,
								Ciclo_Facturacion: 1
							}
						},
						{
							"\$limit": 1
						}
					],
					"as": "facturacion"
				}
			},
			{
				"\$set": {
					ciclo_facturacion_numero: {
						"\$convert": {
							"input": {
								"\$arrayElemAt": ["\$facturacion.Ciclo_Facturacion", 0]
							},
							to: "int",
							onError: null,
							onNull: null
						}
					}
				}
			},
			{
				"\$lookup": {
					from: "PAR_CICLO_FACTURACION",
					localField: "ciclo_facturacion_numero",
					foreignField: "Ciclo_Facturacion",
					pipeline: [
						{
							"\$project": {
								"_id": 0,
								PAM_Schedule: 1
							}
						},
						{
							"\$limit": 1
						}
					],
					"as": "ciclo_estandar"
				}
			},
			{
				"\$lookup": {
					from: "PAR_CICLO_FACTURACION_NEGOCIOS",
					localField: "ciclo_facturacion_numero",
					foreignField: "Ciclo_Facturacion",
					pipeline: [
						{
							"\$project": {
								"_id": 0,
								PAM_Schedule: 1
							}
						},
						{
							"\$limit": 1
						}
					],
					"as": "ciclo_negocios"
				}
			},
			{
				"\$lookup": {
					from: "PAR_CICLO_FACTURACION_FIJO_MOVIL",
					localField: "ciclo_facturacion_numero",
					foreignField: "Ciclo_Facturacion",
					pipeline: [
						{
							"\$project": {
								"_id": 0,
								PAM_Schedule: 1
							}
						},
						{
							"\$limit": 1
						}
					],
					"as": "ciclo_fijo_movil"
				}
			},
			{
				"\$set": {
					Dia_Recarga_Original: {
						"\$convert": {
							"input": {
								"\$ifNull": [
									{ "\$arrayElemAt": ["\$ciclo_estandar.PAM_Schedule", 0] },
									{
										"\$ifNull": [
											{ "\$arrayElemAt": ["\$ciclo_negocios.PAM_Schedule", 0] },
											{ "\$arrayElemAt": ["\$ciclo_fijo_movil.PAM_Schedule", 0] }
										]
									}
								]
							},
							to: "int",
							onError: null,
							onNull: null
						}
					}
				}
			},
			{
				"\$set": {
					Dia_Recarga_Recursos: {
						"\$cond": [
							{ "\$eq": ["\$Dia_Recarga_Original", null] },
							null,
							{
								"\$let": {
									vars: {
										residuo: { "\$mod": ["\$Dia_Recarga_Original", 5] }
									},
									in: {
										"\$let": {
											vars: {
												diaMasCercano: {
													"\$switch": {
														branches: [
															{
																"case": { "\$eq": ["\$\$residuo", 0] },
																then: "\$Dia_Recarga_Original"
															},
															{
																"case": { "\$lte": ["\$\$residuo", 2] },
																then: { "\$subtract": ["\$Dia_Recarga_Original", "\$\$residuo"] }
															}
														],
														"default": {
															"\$add": [
																"\$Dia_Recarga_Original",
																{ "\$subtract": [5, "\$\$residuo"] }
															]
														}
													}
												}
											},
											in: {
												"\$cond": [
													{ "\$lt": ["\$\$diaMasCercano", 5] },
													5,
													{
														"\$cond": [
															{ "\$gt": ["\$\$diaMasCercano", 30] },
															30,
															"\$\$diaMasCercano"
														]
													}
												]
											}
										}
									}
								}
							}
						]
					}
				}
			},
			{
				"\$project": {
					"_id": 0,
					Linea: "\$Numero_Conexion",
					Estado_Servicio: "\$Estado",
					Cuenta_Facturacion: 1,
					Dia_Recarga_Original: 1,
					Dia_Recarga_Recursos: 1
				}
			}
		],
		cursor: {}
	}
}

%dw 2.0
output application/json
var nowDt = (now() >> "America/Bogota") as String { format: "yyyy-MM-dd'T'HH:mm:ss.SSSXXX" }
---
{
	query: {
		update: p('mongo-db-sapi.collections.resource-sharing-panel') default "DASHBOARD_COMPARTE_RECURSOS",
		updates: [{
			q: {
				Numero_Conexion: vars.inputPayload.connectionNumber
			},
			u: {
				"\$set": {
					Numero_Conexion: vars.inputPayload.connectionNumber,
					Fecha_Modificacion: { "\$date": nowDt }
				},
				"\$push": {
					Lista_Abonados: {
						Ciclo_Charging: vars.cicloCharging,
						Fecha_Subscripcion: { "\$date": nowDt },
						Numero_Conexion: vars.inputPayload.referredConnectionNumber,
						Producto: null
					}
				}
			},
			upsert: true,
			multi: false
		}]
	}
}

%dw 2.0
output application/json
var nowDt = (now() >> "America/Bogota") as String { format: "yyyy-MM-dd'T'HH:mm:ss.SSSXXX" }
var padre = vars.inputPayload.connectionNumber
var abonado = vars.inputPayload.referredConnectionNumber
---
{
	codeResponse: payload.codigo default "200",
	responseMessage: "The request was successful",
	thirdParty: {
		connectionNumber: padre,
		subscriber: {
			chargingCycle: vars.cicloCharging,
			subscriptionDate: nowDt,
			connectionNumber: abonado,
			product: null
		}
	}
}

%dw 2.0
output application/json
var nowDt = (now() >> "America/Bogota") as String { format: "yyyy-MM-dd'T'HH:mm:ss.SSSXXX" }
var rawPadre = vars.parameters.connectionNumber default vars.parameters.NUMERO_CONEXION
var rawAbonado = vars.parameters.referredConnectionNumber default vars.parameters.NUMERO_CONEXION_ABONADO
var padre = if (rawPadre is Array) (rawPadre[0] as String) else (rawPadre as String)
var abonado = if (rawAbonado is Array) (rawAbonado[0] as String) else (rawAbonado as String)
---
{
	query: {
		update: p('mongo-db-sapi.collections.resource-sharing-panel') default "DASHBOARD_COMPARTE_RECURSOS",
		updates: [{
			q: {
				Numero_Conexion: padre
			},
			u: {
				"\$pull": {
					Lista_Abonados: {
						Numero_Conexion: abonado
					}
				},
				"\$set": {
					Fecha_Modificacion: { "\$date": nowDt }
				}
			},
			multi: false
		}]
	}
}

%dw 2.0
output application/json
var body = if (payload is String) read(payload, "application/json") else payload
var rawPadre = vars.parameters.connectionNumber
var rawAbonado = vars.parameters.referredConnectionNumber
var padre = if (rawPadre is Array) (rawPadre[0] as String) else (rawPadre as String)
var abonado = if (rawAbonado is Array) (rawAbonado[0] as String) else (rawAbonado as String)
---
{
	codeResponse: body.codigo default "200",
	responseMessage: "The request was successful",
	thirdParty: {
		connectionNumber: padre,
		subscriber: {
			connectionNumber: abonado
		}
	}
}

%dw 2.0
output application/json
---
{
	query: {
		find: "MDM_SERVICIO_ACTIVO",
		filter: {
			Numero_Conexion: vars.connectionNumber,
			Estado: { "\$in": ["Activo", "Suspendido"] }
		},
		limit: 1
	}
}

%dw 2.0
output application/json
---
{
	status: 404,
	code: "NOT_FOUND",
	message: {
		message: "No ETB plan found for connectionNumber " ++ (vars.connectionNumber default "")
	},
	messageServer: "",
	cause: [{
		origin: "business-papi-services-v2",
		message: "Parent connection has no active or suspended service plan in ETB"
	}]
}

%dw 2.0
output application/json
---
{
	query: {
		aggregate: "MDM_SERVICIO_ACTIVO",
		pipeline: [
			{
				"\$match": {
					Numero_Conexion: vars.connectionNumber
				}
			},
			{
				"\$set": {
					id_catalogo: {
						"\$arrayElemAt": ["\$Bundles.id_catalogo", 0]
					}
				}
			},
			{
				"\$set": {
					numero_plan: {
						"\$convert": {
							"input": "\$id_catalogo",
							"to": "int",
							onError: null,
							onNull: null
						}
					}
				}
			},
			{
				"\$lookup": {
					"from": "CMP_OFERTA_PRODUCTO",
					"let": {
						idPlan: "\$numero_plan"
					},
					pipeline: [
						{
							"\$match": {
								"\$expr": {
									"\$and": [
										{ "\$eq": ["\$num_agrupacion", "\$\$idPlan"] },
										{ "\$eq": ["\$secuencia", 0] },
										{ "\$eq": ["\$estado", "Activo"] }
									]
								}
							}
						},
						{
							"\$set": {
								pasagigas: {
									"\$arrayElemAt": [{
										"\$filter": {
											"input": { "\$ifNull": ["\$parametros_bundle", []] },
											"as": "p",
											"cond": { "\$eq": ["\$\$p.parametro", "LINEAS PASAGIGAS"] }
										}
									}, 0]
								}
							}
						},
						{
							"\$project": {
								"_id": 0,
								cantidad: {
									"\$convert": {
										"input": "\$pasagigas.valor",
										"to": "int",
										onError: 0,
										onNull: 0
									}
								}
							}
						}
					],
					"as": "beneficio"
				}
			},
			{
				"\$project": {
					"_id": 0,
					Linea: "\$Numero_Conexion",
					Cantidad_Lineas_Permitidas: {
						"\$ifNull": [{ "\$arrayElemAt": ["\$beneficio.cantidad", 0] }, 0]
					}
				}
			}
		],
		cursor: {}
	}
}

%dw 2.0
output application/json
---
{
	query: {
		find: "BOT_PARAMETRIZATION",
		filter: {
			Code: "PARAMETROS_FUNCIONALES_PASAGIGAS"
		},
		sort: {
			"_id": -1
		},
		limit: 1
	}
}
